import type { ConsoleId } from "@/lib/consoles/types";

const BASE = process.env.NEXT_PUBLIC_BASE_PATH ?? "";

export type BundledGameMeta = {
  title: string;
  coverUrl: string;
  author?: string;
};

// SHA-1 fingerprints generated by EmuRM's ROM worker. These make recognition
// global and filename-independent for every visitor of the deployed site.
const BUNDLED_GAMES: Record<string, BundledGameMeta> = {
  // Earlier EmuRM customized builds — keep these so existing libraries also
  // receive the public cover after the site update.
  "62c519d214757a2286ba60da42dd7d20500d7a76": {
    title: "علاء الدين — نسخة أبو سلمان",
    coverUrl: `${BASE}/boxart/aladdin-arabic-abu00salman.jpg`,
    author: "الحلم المتجدد للتعريب • تخصيص أبو سلمان",
  },
  "5724365e16ef22506ea1ec5855656405761f88bd": {
    title: "علاء الدين — نسخة أبو سلمان",
    coverUrl: `${BASE}/boxart/aladdin-arabic-abu00salman.jpg`,
    author: "الحلم المتجدد للتعريب • تخصيص أبو سلمان",
  },
  // ETR Dream / Aladdin Arabic A 0.9.9
  "7a011936db0438c69fbe3032cceafd1200b78e3c": {
    title: "علاء الدين — النسخة العربية",
    coverUrl: `${BASE}/boxart/aladdin-arabic-abu00salman.jpg`,
    author: "الحلم المتجدد للتعريب",
  },
  // EmuRM customized build with abu00salman credit
  "e0bd238722bbbff90047b6c81f84b04c47963b79": {
    title: "علاء الدين — نسخة أبو سلمان",
    coverUrl: `${BASE}/boxart/aladdin-arabic-abu00salman.jpg`,
    author: "الحلم المتجدد للتعريب • تخصيص أبو سلمان",
  },
};

export function bundledGameMeta(id: string): BundledGameMeta | null {
  return BUNDLED_GAMES[id.toLowerCase()] ?? null;
}

/**
 * Curated local covers for custom/localized ROMs whose filenames do not exist in
 * libretro-thumbnails. Served with the app, so they work for every user and offline.
 */
export function bundledCoverUrl(
  consoleId: ConsoleId,
  fileNameOrTitle: string,
  romId?: string,
): string | null {
  if (consoleId !== "md") return null;

  if (romId) {
    const known = bundledGameMeta(romId);
    if (known) return known.coverUrl;
  }

  const s = fileNameOrTitle.toLowerCase().replace(/[_]+/g, " ");
  const isAladdinArabic = s.includes("aladdin") && (s.includes("arabic") || s.includes("abu00salman"));
  if (isAladdinArabic) return `${BASE}/boxart/aladdin-arabic-abu00salman.jpg`;
  return null;
}

export async function fetchBundledCover(
  consoleId: ConsoleId,
  fileName: string,
  title: string,
  romId?: string,
): Promise<Blob | null> {
  const url = bundledCoverUrl(consoleId, `${fileName} ${title}`, romId);
  if (!url) return null;
  try {
    const res = await fetch(url);
    if (!res.ok) return null;
    const blob = await res.blob();
    return blob.size ? blob : null;
  } catch {
    return null;
  }
}
